function vr_filtration(points, max_dim):
    Sigma <- {empty} union { nonempty subsets of vertices of size <= max_dim + 1 }
    for sigma in Sigma:
        if |sigma| <= 1: w[sigma] <- 0
        else:            w[sigma] <- max over distinct x,y in sigma of dist(x, y)
    return w
